**`packages/http/src/HttpRouter.ts`** — dispatch path becomes a pure function of context.

```diff
-const currentRequest = FiberRef.unsafeMake<Request | null>(null)
-
 export const make = (routes: ReadonlyArray<Route>) => {
-  return Effect.gen(function* () {
-    const req = yield* FiberRef.get(currentRequest)
-    if (req === null) return new Response(null, { status: 500 })
-    const ctx: HandlerCtx = { req }
+  return (ctx: RequestContext) => Effect.gen(function* () {
     for (const route of routes) {
-      const match = route.match(req.url, req.method)
+      const match = route.match(ctx.url.pathname, ctx.req.method)
       if (match) return yield* route.handler(ctx)
     }
     return new Response(null, { status: 404 })
   })
 }
```

**`packages/http/src/RequestContext.ts`** — new module, 24 lines, no implementation logic.

```ts
export interface RequestContext {
  readonly req: Request
  readonly url: URL
  readonly params: ReadonlyMap<string, string>
  readonly signal: AbortSignal
}

export const make = (req: Request, params: ReadonlyMap<string, string>): RequestContext => ({
  req,
  url: new URL(req.url),
  params,
  signal: req.signal,
})
```

